#![cfg(feature = "unstable-dynamic")]

use std::path::Path;
use clap::{Arg, ArgAction, ArgGroup, Command};

fn complete_raw(cmd: &mut Command, args: Vec<&str>, arg_index: usize) -> Vec<String> {
    clap_complete::engine::complete(
        cmd,
        args.into_iter().map(Into::into).collect(),
        arg_index,
        None::<&Path>,
    )
    .unwrap()
    .into_iter()
    .map(|c| c.get_value().to_str().unwrap().to_owned())
    .collect()
}

fn cmd() -> Command {
    Command::new("app")
        .arg(Arg::new("safe").long("safe").action(ArgAction::SetTrue))
        .arg(
            Arg::new("fast")
                .long("fast")
                .visible_alias("quick")
                .action(ArgAction::SetTrue)
                .conflicts_with("safe"),
        )
        .arg(Arg::new("tag").long("tag").action(ArgAction::SetTrue))
        .arg(Arg::new("file").long("file").action(ArgAction::SetTrue))
        .group(
            ArgGroup::new("payload")
                .args(["tag", "file"])
                .conflicts_with("fast"),
        )
}

#[test]
fn scratch_fast() {
    let mut c = cmd();
    let r = complete_raw(&mut c, vec!["app", "--fast", ""], 2);
    println!("fast -> {r:?}");
    assert_eq!(r, vec!["--fast", "--help"]);
}

#[test]
fn scratch_tag() {
    let mut c = cmd();
    let r = complete_raw(&mut c, vec!["app", "--tag", ""], 2);
    println!("tag -> {r:?}");
