}

#[test]
fn scratch_file() {
    let mut c = cmd();
    let r = complete_raw(&mut c, vec!["app", "--file", ""], 2);
    println!("file -> {r:?}");
    assert_eq!(r, vec!["--safe", "--file", "--help"]);
}

#[test]
fn scratch_no_binary_name() {
    let mut c = cmd().no_binary_name(true);
    let r = complete_raw(&mut c, vec!["--fast", ""], 1);
