#[test]
fn suggest_conflicting_args() {
    fn command() -> Command {
        Command::new("exhaustive")
            .arg(
                clap::Arg::new("safe")
                    .long("safe")
                    .action(clap::ArgAction::SetTrue),
            )
            .arg(
                clap::Arg::new("fast")
                    .long("fast")
                    .visible_alias("quick")
                    .alias("speedy")
                    .action(clap::ArgAction::SetTrue)
                    .conflicts_with("safe"),
            )
            .arg(
                clap::Arg::new("tag")
                    .long("tag")
                    .action(clap::ArgAction::SetTrue),
            )
            .arg(
                clap::Arg::new("file")
                    .long("file")
                    .action(clap::ArgAction::SetTrue),
            )
            .group(
                clap::ArgGroup::new("payload")
                    .args(["tag", "file"])
                    .conflicts_with("fast"),
            )
    }

    assert_data_eq!(
        complete!(command(), "--fast [TAB]"),
        snapbox::str![[r#"
--fast
--help	Print help
"#]],
    );

    assert_data_eq!(
        complete!(command(), "--tag [TAB]"),
        snapbox::str![[r#"
--safe
--tag
--help	Print help
"#]],
    );

    // Conflicts are bidirectional: `--safe` hides `--fast` and its aliases,
    // while the unrelated `payload` group stays available.
    assert_data_eq!(
        complete!(command(), "--safe [TAB]"),
        snapbox::str![[r#"
--safe
--tag
--file
--help	Print help
"#]],
    );

    // A non-`multiple` group makes its members conflict with each other.
    assert_data_eq!(
        complete!(command(), "--file [TAB]"),
        snapbox::str![[r#"
--safe
--file
--help	Print help
"#]],
    );

    // Prefix-completion filters aliases too, including hidden ones.
    assert_data_eq!(
        complete!(command(), "--fast --q[TAB]"),
        snapbox::str![""]
    );
    assert_data_eq!(
        complete!(command(), "--fast --spe[TAB]"),
        snapbox::str![""]
    );

    // A value given to an option is not mistaken for an option name.
    assert_data_eq!(
        complete!(command(), "--tag --safe [TAB]"),
        snapbox::str![[r#"
--safe
--tag
--help	Print help
"#]],
    );
}

