fn suggest_conflicts_with_nested_group() {
    let mut cmd = Command::new("exhaustive")
        .arg(clap::Arg::new("a").long("a").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("b").long("b").action(clap::ArgAction::SetTrue))
        .arg(
